import { useEffect } from 'react';

// Premium chime sound effect URL (royalty-free luxury UI sound)
const CHIME_URL = 'data:audio/wav;base64,';

export function playWorkoutCompleteSound() {
  try {
    const audio = new Audio(CHIME_URL);
    audio.volume = 0.5;
    audio.play().catch(err => console.log('Audio play failed:', err));
  } catch (error) {
    console.log('Audio error:', error);
  }
}

export default function WorkoutCompleteSound({ onComplete }) {
  useEffect(() => {
    if (onComplete) {
      playWorkoutCompleteSound();
    }
  }, [onComplete]);

  return null;
}